// === NODE 2: Kiem tra du lieu dau vao (Input Validation) ===
const body = $input.first().json.body;

const errors = [];

if (!body.task_id) errors.push('Thieu task_id');
if (!body.old_status) errors.push('Thieu old_status');
if (!body.new_status) errors.push('Thieu new_status');

const validStatuses = ['TODO', 'IN_PROGRESS', 'IN_REVIEW', 'DONE'];
if (body.old_status && !validStatuses.includes(body.old_status)) {
  errors.push('old_status khong hop le: ' + body.old_status);
}
if (body.new_status && !validStatuses.includes(body.new_status)) {
  errors.push('new_status khong hop le: ' + body.new_status);
}

if (body.old_status === body.new_status) {
  errors.push('old_status va new_status giong nhau, khong can xu ly');
}

return [{
  json: {
    is_valid: errors.length === 0,
    errors: errors,
    body: body
  }
}];

// === NODE 9: Tinh Lead Time + Cycle Time + Phan tich chuyen doi ===
const webhookData = $('Code - Validate Input').first().json.body;
const taskInfo = $('Postgres - Get Full Task Info').first().json;

const now = new Date();
const createdAt = new Date(taskInfo.created_at);
const lastUpdatedAt = new Date(taskInfo.updated_at);

// 1. Lead Time: thoi gian tu khi tao -> hoan thanh (chi khi DONE)
let lead_time_hours = null;
if (webhookData.new_status === 'DONE') {
  lead_time_hours = Math.round(
    ((now.getTime() - createdAt.getTime()) / (1000 * 60 * 60)) * 100
  ) / 100;
}

// 2. Cycle Time: thoi gian task nam o trang thai cu (tu lan update truoc -> bay gio)
const cycle_time_hours = Math.round(
  ((now.getTime() - lastUpdatedAt.getTime()) / (1000 * 60 * 60)) * 100
) / 100;

// 3. Transition Analysis: phan loai luong chuyen doi
const transitionMap = {
  'TODO->IN_PROGRESS': 'STARTED',
  'IN_PROGRESS->IN_REVIEW': 'SUBMITTED_FOR_REVIEW',
  'IN_REVIEW->DONE': 'APPROVED_AND_COMPLETED',
  'IN_REVIEW->IN_PROGRESS': 'REVIEW_REJECTED',
  'TODO->DONE': 'FAST_TRACK_COMPLETED',
  'IN_PROGRESS->TODO': 'ROLLBACK_TO_TODO',
  'IN_PROGRESS->DONE': 'DIRECT_COMPLETED'
};
const transitionKey = webhookData.old_status + '->' + webhookData.new_status;
const transition_type = transitionMap[transitionKey] || 'CUSTOM_TRANSITION';

// 4. Kiem tra qua han
const is_overdue = taskInfo.due_date ? new Date(taskInfo.due_date) < now : false;

// 5. Build message
let message = '';
if (lead_time_hours !== null) {
  message = 'Task hoan thanh! Lead time: ' + lead_time_hours + ' gio';
  if (is_overdue) message += ' (DA QUA HAN!)';
} else {
  message = webhookData.old_status + ' -> ' + webhookData.new_status + ' (' + transition_type + ')';
}

return [{
  json: {
    task_id: webhookData.task_id,
    task_title: taskInfo.task_title,
    project_id: taskInfo.project_id,
    project_name: taskInfo.project_name,
    assignee_id: taskInfo.assignee_id,
    assignee_name: taskInfo.assignee_name,
    assignee_email: taskInfo.assignee_email,
    priority: taskInfo.priority,
    story_points: taskInfo.story_points,
    old_status: webhookData.old_status,
    new_status: webhookData.new_status,
    changed_by: webhookData.changed_by || null,
    lead_time_hours: lead_time_hours,
    cycle_time_hours: cycle_time_hours,
    transition_type: transition_type,
    is_overdue: is_overdue,
    is_completed: webhookData.new_status === 'DONE',
    was_bottleneck: taskInfo.is_bottleneck,
    timestamp: webhookData.timestamp || now.toISOString(),
    message: message
  }
}];
